<script setup lang="ts">
import { permissionDirective as vPermission, canPermission } from '../permissions'
import type { UserInfo } from '../api'
import { adminRoute, navigateAdmin } from '../navigation'
import { getResearchNote } from '../xhs-research'
import { newIdea, nextWorkflow, workflowStatus, useWorkflow } from '../xhs-workflow'
import XhsWorkflowFrame from './XhsWorkflowFrame.vue'
import XhsWorkflowLinks from './XhsWorkflowLinks.vue'
const props = defineProps<{ user: UserInfo }>()
const w = useWorkflow('ideas', newIdea, async (_parent, data) => {
  const source = new URLSearchParams(adminRoute.query).get('source')
  if (!source) return
  const note = await getResearchNote(source)
  Object.assign(data, { grade: note.grade, subject: note.subject, keyword: note.keyword })
  data.source_note_id = source
  data.title = note.title.slice(0, 120) || '新选题'
  data.notes = note.remark || ''
}, props.user.id)
const { items, total, page, q, filter, record, data, parent, editing, busy, loading, error, notice, dirty } = w
async function createMaterial() { if (await w.save()) nextWorkflow('materials', record.value!.id) }
const statuses = ['inbox', 'planned', 'creating', 'done', 'archived']
</script>
<template><XhsWorkflowFrame title="选题库" description="把参考内容变成明确的制作计划：为谁做、解决什么问题、做出什么差异。" create-label="新建选题" v-bind="{ items,total,page,editing,busy,loading,error,notice,dirty,statuses }" :backup="w.backup" @reset="w.resetFilters" v-model:q="q" v-model:filter="filter" @open="w.open" @back="w.back" @save="w.save" @search="w.loadList" @page="page=$event"><template #guide><div class="workflow-step">先挑一个具体知识点，再明确读者和资料形式。也可以在采集结果中点击“转为选题”。<UButton v-permission="'xhsResearch:view'" label="去采集调研" variant="link" @click="navigateAdmin('xhsResearch')" /></div></template><XhsWorkflowLinks :record="record" :parent="parent" /><div class="workflow-card workflow-grid"><label class="workflow-field workflow-wide"><span>选题名称</span><UInput :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.title" aria-label="选题名称" maxlength="120" placeholder="例如：一年级找规律分层练习" /></label><label class="workflow-field"><span>年级</span><UInput :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.grade" maxlength="20" /></label><label class="workflow-field"><span>科目</span><UInput :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.subject" maxlength="20" /></label><label class="workflow-field"><span>知识点</span><UInput :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.keyword" maxlength="100" /></label><label class="workflow-field"><span>目标读者</span><UInput :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.audience" maxlength="200" placeholder="例如：陪一年级孩子练习的家长" /></label><label class="workflow-field"><span>资料形式</span><UInput :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.format" maxlength="80" placeholder="分层练习 / 错题整理 / 方法卡片" /></label><label class="workflow-field"><span>计划完成日期</span><input class="workflow-native" type="date" :value="data.due_date || ''" @input="data.due_date=($event.target as HTMLInputElement).value || null" /></label><label class="workflow-field"><span>优先级</span><USelect :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.priority" :items="[{value:'high',label:'优先做'},{value:'normal',label:'正常'},{value:'low',label:'以后再做'}]" /></label><label class="workflow-field"><span>状态</span><USelect :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.status" :items="statuses.map(value=>({value,label:workflowStatus(value)}))" /></label><label class="workflow-field workflow-wide"><span>要解决的问题</span><UTextarea :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.problem" :rows="3" maxlength="2000" placeholder="孩子在哪一步容易出错？家长需要什么帮助？" /></label><label class="workflow-field workflow-wide"><span>自己的切入点</span><UTextarea :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.angle" :rows="3" maxlength="2000" placeholder="例如：按难度分三组，每组加一道带讲解的例题" /></label><label class="workflow-field workflow-wide"><span>参考与补充说明</span><UTextarea :disabled="!canPermission('xhsIdeas:' + (record ? 'update' : 'create'))" v-model="data.notes" :rows="3" maxlength="4000" /></label><UButton v-permission="'xhsAnalytics:view'" v-if="data.source_publication_id" label="查看来源复盘" variant="link" @click="navigateAdmin('xhsAnalytics',{id:data.source_publication_id})" /><a v-if="data.source_note_id" :href="`https://www.xiaohongshu.com/explore/${encodeURIComponent(data.source_note_id)}`" target="_blank" rel="noreferrer">打开关联参考笔记 ↗</a></div><div class="workflow-step workflow-actions"><span>下一步：把这个计划做成原创练习资料。</span><UButton v-permission="'xhsMaterials:create'" label="保存并制作资料" :disabled="busy" @click="createMaterial" /></div></XhsWorkflowFrame></template>
